import { useEffect, useState, useCallback } from 'react';
import { useEvents } from '../context/EventContext';
import { useAuth } from '../context/AuthContext';
import { useToast } from '../context/ToastContext';
import EventCard from '../components/EventCard';
import EventModal from '../components/EventModal';
import { LoadingSpinner } from '../components/ProtectedRoute';

const CATEGORIES = ['', 'conference', 'workshop', 'webinar', 'meetup', 'concert', 'sports', 'other'];
const STATUSES = ['', 'draft', 'published', 'cancelled', 'completed'];
const SORTS = [
  { value: '-createdAt', label: 'Newest first' },
  { value: 'createdAt', label: 'Oldest first' },
  { value: 'startDate', label: 'Start date ↑' },
  { value: '-startDate', label: 'Start date ↓' },
  { value: '-registeredCount', label: 'Most popular' },
];

export default function Events() {
  const { events, loading, pagination, fetchEvents, createEvent, updateEvent, deleteEvent } = useEvents();
  const { user } = useAuth();
  const { toast } = useToast();

  const [filters, setFilters] = useState({ search: '', category: '', status: '', sort: '-createdAt', page: 1 });
  const [modalOpen, setModalOpen] = useState(false);
  const [editingEvent, setEditingEvent] = useState(null);

  const canCreate = user?.role === 'organiser' || user?.role === 'admin';

  const load = useCallback(() => {
    const params = {};
    if (filters.search) params.search = filters.search;
    if (filters.category) params.category = filters.category;
    if (filters.status) params.status = filters.status;
    params.sort = filters.sort;
    params.page = filters.page;
    fetchEvents(params);
  }, [filters, fetchEvents]);

  useEffect(() => { load(); }, [load]);

  const handleFilterChange = (key, value) => setFilters((f) => ({ ...f, [key]: value, page: 1 }));

  const handleSave = async (data) => {
    try {
      if (editingEvent) {
        await updateEvent(editingEvent._id, data);
        toast.success('Event updated!');
      } else {
        await createEvent(data);
        toast.success('Event created!');
      }
      setModalOpen(false);
      setEditingEvent(null);
      load();
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to save event');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this event? This cannot be undone.')) return;
    try {
      await deleteEvent(id);
      toast.success('Event deleted');
    } catch (err) {
      toast.error('Failed to delete event');
    }
  };

  const handleEdit = (event) => { setEditingEvent(event); setModalOpen(true); };

  const selectStyle = {
    padding: '8px 12px', borderRadius: 8, border: '1px solid #e5e7eb',
    fontSize: 13, background: '#fff', cursor: 'pointer', outline: 'none',
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h2 style={{ margin: 0, fontSize: 22, fontWeight: 700, color: '#111827' }}>Events</h2>
          <p style={{ margin: '2px 0 0', fontSize: 13, color: '#6b7280' }}>{pagination.total} event{pagination.total !== 1 ? 's' : ''} found</p>
        </div>
        {canCreate && (
          <button onClick={() => { setEditingEvent(null); setModalOpen(true); }} style={{
            padding: '10px 20px', borderRadius: 8, border: 'none',
            background: '#6366f1', color: '#fff', fontWeight: 600, fontSize: 14, cursor: 'pointer',
          }}>
            + Create Event
          </button>
        )}
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10 }}>
        <input
          type="text" placeholder="Search events..."
          value={filters.search}
          onChange={(e) => handleFilterChange('search', e.target.value)}
          style={{ ...selectStyle, flex: '1 1 180px', cursor: 'text' }}
        />
        <select value={filters.category} onChange={(e) => handleFilterChange('category', e.target.value)} style={selectStyle}>
          {CATEGORIES.map((c) => <option key={c} value={c}>{c || 'All categories'}</option>)}
        </select>
        <select value={filters.status} onChange={(e) => handleFilterChange('status', e.target.value)} style={selectStyle}>
          {STATUSES.map((s) => <option key={s} value={s}>{s || 'All statuses'}</option>)}
        </select>
        <select value={filters.sort} onChange={(e) => handleFilterChange('sort', e.target.value)} style={selectStyle}>
          {SORTS.map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
        </select>
      </div>

      {/* Events grid */}
      {loading ? (
        <LoadingSpinner />
      ) : events.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 0', color: '#9ca3af' }}>
          <div style={{ fontSize: 48, marginBottom: 12 }}>🗓️</div>
          <p style={{ fontSize: 16 }}>No events found</p>
          {canCreate && <p style={{ fontSize: 13 }}>Create your first event to get started!</p>}
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 16 }}>
          {events.map((event) => (
            <EventCard key={event._id} event={event} onEdit={handleEdit} onDelete={handleDelete} />
          ))}
        </div>
      )}

      {/* Pagination */}
      {pagination.pages > 1 && (
        <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginTop: 8 }}>
          {Array.from({ length: pagination.pages }, (_, i) => i + 1).map((p) => (
            <button key={p} onClick={() => setFilters((f) => ({ ...f, page: p }))} style={{
              width: 36, height: 36, borderRadius: 8, border: '1px solid #e5e7eb',
              background: p === filters.page ? '#6366f1' : '#fff',
              color: p === filters.page ? '#fff' : '#374151',
              fontWeight: 600, fontSize: 14, cursor: 'pointer',
            }}>{p}</button>
          ))}
        </div>
      )}

      {/* Modal */}
      {modalOpen && (
        <EventModal
          event={editingEvent}
          onSave={handleSave}
          onClose={() => { setModalOpen(false); setEditingEvent(null); }}
        />
      )}
    </div>
  );
}
